/* Action-first presentation. Existing evidence and decision rules stay authoritative. */
let recordView='all';
const pendingKeys=c=>FIELD_KEYS.filter(k=>c.fields[k].comparison===null||c.fields[k].comparison==='MISMATCH'&&!c.fields[k].verified);
const routeFor=c=>c.processing?'progress':(c.category!=='BL_COMPARISON'?'email/':c.pairIssue?'pair/':'review/')+c.id;
function taskLabel(c){
  if(c.pairIssue)return 'Choose documents';
  if(c.docIssue==='missing_bl')return 'Upload BL';
  if(mode(c)!=='needs')return c.processing?'View progress':'View result';
  if(!c.docIssue&&!c.processingError&&pendingKeys(c).length>1)return `Handle ${pendingKeys(c).length} issues`;
  return next(c);
}
shell=function(content,name,active='inbox'){
  const n=cases.filter(c=>mode(c)==='needs').length;
  app.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#inbox"><span class="brand-mark">❯</span>Verity</a><nav class="nav" aria-label="Main navigation">${[['inbox','inbox','To do'],['records','layers','All records'],['exports','export','Results']].map(([key,ic,label])=>`<a href="#${key}" ${key==='inbox'?'data-action="nav-inbox"':''} class="${active===key?'active':''}">${icon(ic)}${label}${key==='inbox'?`<span class="count">${n}</span>`:''}</a>`).join('')}</nav><div class="side-bottom"><div class="demo-note"><strong>Demo workspace</strong><p>Preset cases · saved locally</p><details class="demo-tools"><summary>Demo tools</summary><a href="#screens">Explore all scenarios</a><button class="link" data-action="reset">Reset examples</button></details></div></div></aside><main class="workspace"><header class="topbar"><span class="crumb">${esc(name)}</span><div class="top-right"><span>Preset data · no live processing</span><span class="avatar">MW</span></div><span class="mobile-demo">Preset demo</span></header>${content}</main></div>`;
};
function queueRow(c,result=false){return `<div class="task-row"><div class="task-identity"><span class="task-file">${icon('file')}</span><div><strong>${esc(c.id)}</strong><small>${esc(c.company)}</small></div></div><div class="task-need"><span>${esc(finding(c))}</span>${c.category!=='BL_COMPARISON'?`<small>${esc(category(c))}</small>`:''}</div><a class="btn ${result?'':'task-action'}" href="#${routeFor(c)}">${esc(result?'View result':taskLabel(c))}${icon('arrow')}</a></div>`}
renderInbox=function(page){
  const home=page==='inbox';if(page==='completed')recordView='complete';
  const needs=cases.filter(c=>mode(c)==='needs').length, running=cases.filter(c=>mode(c)==='processing').length;
  const list=cases.filter(c=>(home?mode(c)==='needs':recordView==='all'||mode(c)===recordView)&&(!search||`${c.id} ${c.company} ${finding(c)}`.toLowerCase().includes(search.toLowerCase())));
  shell(`<section class="page queue-page"><div class="page-head"><div><span class="eyebrow">${home?'YOUR WORK QUEUE':'BATCH EX-DEMO-01'}</span><h1>${home?'Let’s clear your queue.':'All records'}</h1><p>${home?`${needs} cases need your input.`:'Every email, including those that need no comparison.'}</p></div><a class="btn primary" href="#import">${icon('upload')}Import files</a></div>${!home?`<div class="tabs" aria-label="Record status">${[['all','All'],['needs','Needs you'],['processing','Processing'],['complete','Completed']].map(([v,t])=>`<button class="tab ${recordView===v?'active':''}" data-action="record-filter" data-filter="${v}">${t}<b>${v==='all'?cases.length:cases.filter(c=>mode(c)===v).length}</b></button>`).join('')}</div>`:''}<div class="queue-tools"><div class="search">${icon('search')}<input id="search" aria-label="Search cases" placeholder="Find a case or company" value="${esc(search)}"></div>${home&&running?`<button class="quiet" data-action="show-processing">${icon('clock')}${running} processing</button>`:''}</div><div class="task-list"><div class="task-head"><span>CASE</span><span>${home?'WHAT NEEDS YOU':'RESULT'}</span><span></span></div>${list.map(c=>queueRow(c)).join('')||`<div class="empty"><h2>${search?'No matching cases':'You’re up to date.'}</h2><p>${search?'Try a case number or company name.':'Your completed reviews are in All records.'}</p></div>`}</div><div class="queue-foot"><span>${list.length} cases</span><a href="#exports">View batch results ${icon('arrow')}</a></div></section>`,home?'To do':'All records',home?'inbox':'records');
};
caseHeader=function(c){return `<div class="case-top"><a href="#inbox" class="back-link">${icon('back')}To do</a><span><strong>${esc(c.id)}</strong><span class="muted"> · ${esc(c.company)}</span></span><button class="quiet" data-action="case-details" data-id="${c.id}">Case details ${icon('layers')}</button></div>`};
const shortCopy={
 missing_value:['SI is missing gross weight','Add source information so we can compare it with the BL.','Upload supporting file'],
 missing_si:['Add the missing SI','This case needs one SI and one BL.','Upload SI'],
 missing_bl:['Add the missing BL','The SI is ready. Add its matching draft BL.','Upload BL'],
 wrong_type:['We need a BL, not this invoice','Upload the draft BL for this booking.','Upload correct BL'],
 scan_illegible:['This scan is still unreadable','One reread did not resolve it. Add a clearer source.','Upload clearer file'],
 separator_ambiguous:['What does 22.000 MT mean?','Confirm the source’s number format before choosing.','Choose interpretation'],
 alias_collision:['Which Portland is this?','Use the country or a confirmed location code.','Choose location'],
 entity_identity:['Are these the same company?','Confirm with an address or business record.','Review company evidence'],
 extraction_incomplete:['Does the original say 3?','The extracted count is 8. Check the source below.','Correct extracted value'],
 evidence_not_located:['Find this field in the original','We could not locate it. Review the full documents.','Record manual finding'],
 port_name_code_conflict:['The port name and code disagree','Confirm the intended location from the source.','Confirm location'],
 alias_not_found:['Confirm this port’s location','Matching names alone do not resolve an unknown port.','Provide location evidence'],
 invalid_container_count:['Is the container count really 0?','Both documents say 0. Ask for corrected information.','Upload corrected information'],
 service_timeout:['We couldn’t read this file','Retry the failed reading stage once.','Retry failed stage'],
 unsupported_format:['We can’t open this file format','Add a PDF, image or supported document.','Upload supported file'],
 mismatch:['These values are different','Check both sources, then record that you reviewed the difference.','Record verified difference'],
 match:['These values agree','No action is needed for this field.','Next issue']
};
function sourceExcerpt(c,side,k){const f=c.fields[k],raw=side==='si'?(f.sourceSI??f.si):(f.sourceBL??f.bl);return `<div class="excerpt"><div class="excerpt-head">${icon('file')}<span>${side.toUpperCase()} · sample source · page 1</span></div><div class="excerpt-value"><span>${LABELS[k]}</span><mark>${esc(raw)}</mark></div><button class="quiet" data-action="original" data-id="${c.id}" data-side="${side}">Open full source ${icon('export')}</button></div>`}
renderReview=function(c){
  if(c.category!=='BL_COMPARISON'){go('email/'+c.id);return}if(c.pairIssue){go('pair/'+c.id);return}
  if(lastReviewCase!==c.id){selectedField=pendingKeys(c).find(k=>c.fields[k].comparison===null)||pendingKeys(c)[0]||'shipper';lastReviewCase=c.id}
  const paused=!!(c.docIssue||c.processingError||c.processing),n=counts(c),issues=FIELD_KEYS.filter(k=>c.fields[k].comparison!=='MATCH');
  const complete=mode(c)==='complete', f=c.fields[selectedField],issue=currentIssue(c,selectedField);
  let [title,body,label]=shortCopy[issue]||['Review this field','More source evidence is needed.','Review evidence'];
  let action=(ISSUE_COPY[issue]||[])[3]||'resolve';
  if(issue==='missing_value')title=`SI is missing ${LABELS[selectedField].toLowerCase()}`;
  if(issue==='mismatch')title=`${LABELS[selectedField]} doesn’t match`;
  if(issue==='service_timeout'&&c.retries){title='The retry didn’t work';body='Keep this case unresolved and use the originals for manual review.';label='Download originals';action='download-originals'}
  const reviewed=f.comparison==='MISMATCH'&&f.verified;
  const tabs=!paused&&issues.length?`<div class="issue-switcher" aria-label="Case issues">${issues.map(k=>`<button data-action="field" data-field="${k}" class="issue-tab ${selectedField===k?'active':''}">${c.fields[k].verified?'✓':c.fields[k].comparison==='MISMATCH'?'≠':'?'} ${LABELS[k]}<small>${c.fields[k].verified?'Reviewed':c.fields[k].comparison==='MISMATCH'?'Difference':'Needs input'}</small></button>`).join('')}</div>`:'';
  const details=`<details class="fold"><summary>${n.match} matched fields</summary><div class="matched-list">${FIELD_KEYS.filter(k=>c.fields[k].comparison==='MATCH').map(k=>`<div><span>${LABELS[k]}</span><span>${esc(c.fields[k].si)}</span><span class="green">✓ Matched</span></div>`).join('')}</div><p class="caption">Matching means SI and BL agree. It does not verify that the SI itself is correct.</p></details>`;
  const completedCard=`<div class="completion"><span class="completion-icon">${icon('check')}</span><h1>${n.diff?'Review complete. Difference retained.':'All 7 fields match.'}</h1><p>${n.diff?`${n.diff} verified difference remains in the report.`:'SI and BL agree on the seven compared fields.'}</p><div class="flex wrap"><a class="btn primary" href="#inbox">Next case ${icon('arrow')}</a><a class="btn" href="#exports">View results</a></div></div>`;
  shell(`<section class="page focus-page">${caseHeader(c)}<div class="focus-wrap">${!paused?`<div class="case-context">${n.diff?`<span class="red">${n.diff} difference${n.diff>1?'s':''}</span>`:''}${n.unresolved?`<span class="amber">${n.unresolved} unresolved</span>`:''}<span>${n.match} matched</span></div>`:''}${complete?completedCard:''}${tabs}${!complete?`<article class="focus-card"><div class="focus-heading"><span class="eyebrow">${paused?'ACTION NEEDED':LABELS[selectedField].toUpperCase()}</span><h1>${esc(title)}</h1><p>${esc(body)}</p></div>${!paused?`<div class="compare-values"><div><span>SI · Reference</span><strong>${f.kind==='MISSING'?'Missing':esc(f.si)}</strong></div><span class="compare-sign">${f.comparison==='MISMATCH'?'≠':'?'}</span><div><span>BL · Draft</span><strong>${esc(f.bl)}</strong></div></div>${issue==='evidence_not_located'?`<div class="evidence-pair full-review">${sourceDoc(c,'si',selectedField,true)}${sourceDoc(c,'bl',selectedField,true)}</div>`:`<div class="excerpt-pair">${sourceExcerpt(c,'si',selectedField)}${sourceExcerpt(c,'bl',selectedField)}</div>`}`:''}<div class="focus-actions">${reviewed?`<span class="green">✓ Reviewed · still different</span>${button('Next issue '+icon('arrow'),'next-field','primary',`data-id="${c.id}"`)}`:`${button(esc(label)+' '+icon('arrow'),action,'primary',`data-id="${c.id}"`)}${button('I can’t resolve this yet','leave','quiet',`data-id="${c.id}"`)}`}</div>${['missing_value','missing_si','missing_bl','wrong_type','invalid_container_count'].includes(issue)?`<details class="alternative"><summary>Another way to follow up</summary>${button('Copy a request for information','copy-request','',`data-id="${c.id}"`)}</details>`:''}</article>`:''}${!paused?details:''}${complete&&n.diff?`<details class="fold"><summary>Verified differences</summary>${issues.map(k=>`<div class="result-difference"><b>${LABELS[k]}</b><span>SI ${esc(c.fields[k].si)} ≠ BL ${esc(c.fields[k].bl)}</span></div>`).join('')}</details>`:''}<p class="sample-caption">Preset evidence for this demo. Original files stay unchanged.</p></div></section>`,c.id);
};
renderPair=function(c){
  if(lastPairCase!==c.id){pairSelection=c.pair?{...c.pair}:{si:'',bl:''};lastPairCase=c.id}
  const option=(side,v,title,sub)=>`<label class="pick-card ${pairSelection[side]===v?'picked':''}"><input type="radio" name="pair-${side}" value="${v}" ${pairSelection[side]===v?'checked':''}><span>${icon('file')}</span><span><strong>${title}</strong><small>${sub}</small></span></label>`;
  shell(`<section class="page focus-page">${caseHeader(c)}<div class="focus-wrap pairing-wrap"><span class="eyebrow">DOCUMENT PAIRING</span><h1>${c.pairIssue?'Which SI should we use?':'Review the selected pair'}</h1><p class="intro">Choose the approved version for booking ${esc(c.booking)}.</p><div class="pair-steps"><section><h2><span class="step-number current">1</span> Select the SI</h2><div class="si-options">${option('si','si-original','Original SI','12 Sep · 3 pages')}${c.type==='pairing'?option('si','si-revision','Revised SI','14 Sep · 3 pages'):''}</div><p class="caption">A newer date does not mean it is approved.</p></section><section><h2><span class="step-number">2</span> Confirm the BL</h2>${option('bl','bl-current','Draft BL',`Booking ${esc(c.booking)} · 14 Sep · 2 pages`)}${c.type==='pairing'?'<details class="fold"><summary>1 other BL excluded</summary><p class="caption">BL_BK-9902_other.pdf belongs to booking BK-9902.</p></details>':''}</section></div><details class="fold"><summary>Inspect sample documents</summary><div class="evidence-pair">${sourceDoc(c,'si','shipper',true)}${sourceDoc(c,'bl','shipper',true)}</div></details><div class="pair-footer">${button('I’m not sure yet','leave','quiet',`data-id="${c.id}"`)}${button('Compare selected pair '+icon('arrow'),'confirm-pair','primary',`data-id="${c.id}" ${!pairSelection.si||!pairSelection.bl?'disabled':''}`)}</div><details class="alternative"><summary>These files cover multiple shipments</summary>${button('Keep for shipment organization','multiple','',`data-id="${c.id}"`)}</details></div></section>`,c.id+' / Choose documents');
};
renderImport=function(){
  shell(`<section class="page"><div class="import-wrap"><a class="back-link" href="#inbox">${icon('back')}To do</a><h1>Add your materials.</h1><p class="intro">Email JSON and its attachments, together.</p><div class="dropzone" id="dropzone"><div class="drop-icon">${icon('upload')}</div><h2>Drop files here</h2><input type="file" id="import-files" multiple accept=".json,.zip,.pdf,.png,.jpg,.jpeg,.tif,.tiff,.txt,.docx,.xlsx" hidden>${button('Choose files','choose-import','primary')}<p class="caption">JSON, ZIP, PDF, images, Word or Excel</p></div>${staged.length?`<div class="staged-simple"><div class="flex between"><h3>${staged.length} files added</h3>${button('Clear','clear-import','quiet')}</div>${staged.map(f=>`<div class="file-staged">${icon('file')}<span class="filename">${esc(f.name)}<small>${esc(f.info||Math.ceil(f.size/1024)+' KB')}</small></span>${badge(f.error?'Check file':'Staged',f.error?'amber':'green')}</div>`).join('')}</div>`:''}${importErrors.map(x=>`<div class="alert amber">${esc(x)}</div>`).join('')}<div class="sample-loader"><div><strong>Try the workflow</strong><p class="caption">Use sample files to explore every review path.</p></div>${button(demoStaged?'Reload examples':'Load example batch','load-demo','')}</div>${demoStaged?`<div class="start-row">${button('Run sample batch '+icon('arrow'),'start-demo','primary')}</div>`:''}<p class="sample-caption">Demo: uploaded files stay local. OCR and AI processing are not connected.</p></div></section>`,'Import files');
  const z=document.getElementById('dropzone');z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('over')});z.addEventListener('dragleave',()=>z.classList.remove('over'));z.addEventListener('drop',e=>{e.preventDefault();stageFiles(e.dataTransfer.files)});
};
renderExports=function(){
  const diffs=cases.filter(c=>c.category==='BL_COMPARISON'&&counts(c).diff).length,needs=cases.filter(c=>mode(c)==='needs').length,done=cases.filter(c=>mode(c)==='complete').length;
  shell(`<section class="page queue-page"><div class="page-head"><div><span class="eyebrow">BATCH EX-DEMO-01</span><h1>Your batch, accounted for.</h1><p>All ${cases.length} emails stay in the report.</p></div>${button(icon('download')+'Download review report','download-report','primary')}</div><div class="result-summary"><div><strong>${done}</strong><span>Completed</span></div><div><strong>${needs}</strong><span>Need action</span></div><div><strong>${diffs}</strong><span>Have differences</span></div></div><div class="export-note">${icon('file')}<span>Internal demo report · JSON</span><button class="quiet" data-action="preview-json">Preview report</button></div><details class="fold export-checks"><summary>Competition submission is not ready</summary><p class="caption">This is preset data. Live processing and unresolved export mappings must be completed before submission.</p>${button('View export checks','export-blocks','')}</details><div class="task-list"><div class="task-head"><span>CASE</span><span>RESULT</span><span></span></div>${cases.map(c=>queueRow(c,true)).join('')}</div><p class="sample-caption">Reviewed differences stay different. Unresolved findings stay visible. Counts can overlap.</p></section>`,'Results','exports');
};
renderProgress=function(){const p=progress||0;const stages=['Read emails','Pair documents','Check fields','Prepare results'];shell(`<section class="page"><div class="import-wrap progress-focus"><span class="eyebrow">SAMPLE BATCH</span><h1>${p>=100?'Ready for your review.':'Preparing your cases.'}</h1><p class="intro">Demo sequence · no live OCR or AI requests.</p><div class="progress-top"><strong>${p}%</strong><span>${p>=100?'Complete':stages[Math.min(3,Math.floor(p/25))]}</span></div><div class="progressbar" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><span style="width:${p}%"></span></div><div class="progress-stages">${stages.map((s,i)=>`<div class="${p>=(i+1)*25?'green':''}">${p>=(i+1)*25?'✓':i+1} ${s}</div>`).join('')}</div>${p>=100?`<a class="btn primary" href="#inbox">Open work queue ${icon('arrow')}</a>`:button('Run / resume sample sequence','resume-progress','primary')}</div></section>`,'Processing')};
const priorHandleAction=handleAction;
handleAction=function(a,b){
  if(a==='record-filter'){recordView=b.dataset.filter;render();return}
  if(a==='show-processing'){recordView='processing';go('records');return}
  const c=getCase(b.dataset.id||route()[1]||selected);
  if(a==='case-details'){openModal('Case details',`<p>${esc(c.id)} · ${esc(c.company)}</p><div class="case-detail-links"><a href="#email/${c.id}" data-action="close-modal">${icon('mail')}Email & classification ${icon('arrow')}</a><a href="#pair/${c.id}" data-action="close-modal">${icon('file')}Document pair ${icon('arrow')}</a><a href="#history/${c.id}" data-action="close-modal">${icon('clock')}Review history ${icon('arrow')}</a></div>${c.sourceVersions?.length?button('Previous source versions','source-versions','',`data-id="${c.id}"`):''}`);return}
  priorHandleAction(a,b);
  if(['verify','save-resolution','sample-support'].includes(a)&&c&&!document.getElementById('modal').open){const nextKey=pendingKeys(c)[0];if(nextKey&&nextKey!==selectedField){selectedField=nextKey;render();toast('Saved. Here’s the next issue in this case.')}}
};
render();
